from functools import wraps

def decorator(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        print('Called')
        return func(*args, **kwargs)
    return wrapper

@decorator
def add(a, b):
    '''Add two numbers'''
    return a + b

print(add(3, 5))
print(add.__name__)
print(add.__doc__)
